ee:message.ee:set-payload:
%dw 2.0
output application/json

var validGrades = Mule::p("var.validGrades")
var validSemesters = Mule::p("var.validSemesters")
var validBranches = Mule::p("var.validBranches")

var isValid =
    (validBranches contains payload.Branch) and
    (validSemesters contains payload.Semester) and
    (validGrades contains payload.Grade) and
    (
        ((["A","B","C"] contains payload.Grade) and (payload.FinalResult == "Pass")) or
        ((["D","E"] contains payload.Grade) and (payload.FinalResult == "Fail"))
    )

---
{
    status: if (isValid) "Success" else "Failure"
}
